 general:[['Basics'],['language','Language','Interface language. Existing prototype copy remains English.','select',['System','English','中文'],'System'],['theme','Theme','Use the system appearance or choose a fixed theme.','select',['System','Light','Dark'],'System'],['size','Interface size','Adjust control spacing and text together.','select',['Comfortable','Compact','Large'],'Comfortable'],['startup','Start at login','Device-specific; excluded from exported configuration.','toggle',null,true],['menubar','Show in menu bar','Keep quick access to Settings and Quit.','toggle',null,true],['launcherKey','Launcher shortcut','Select Record to capture a combination.','shortcut',null,'Alt+Space'],['results','Maximum results','Rows before scrolling; one to twelve.','select',Array.from({length:12},(_,i)=>String(i+1)),'12'],['Search behavior'],['fallback','When no results match','Choose the offered recovery action.','select',['Offer web search','Offer AI','Keep local only'],'Offer web search'],['websearch','Web search','Allow bang searches and the no-results fallback.','toggle',null,true],['remember','Remember last query','Restore your previous query when reopening.','toggle',null,false]],
