 clipboard:[['History'],['clipEnabled','Record clipboard history','Pause recording without deleting your existing items.','toggle',null,true],['clipRetention','Keep history for','Automatically expire unpinned items.','select',['1 day','7 days','30 days','90 days'],'30 days'],['clipTypes','Content to record','Select which clipboard data can appear.','select',['Text and images','Text only','Links only'],'Text and images'],['pasteMode','Default action','Choose what Enter does in clipboard results.','select',['Paste','Copy','Paste as plain text'],'Paste'],['Privacy'],['clipSecrets','Mask sensitive content','Credentials stay masked until explicitly revealed.','toggle',null,true],['clipPasswords','Ignore password-manager content','Respect concealed clipboard flags.','toggle',null,true],['clipPrivate','Pause in private sessions','Do not record while a supported private context is active.','toggle',null,true]],
 windows:[['Layout'],['windowEnabled','Enable window commands','Make resize and move commands searchable.','toggle',null,true],['windowGap','Window gap','Space around tiled windows.','select',['0 px','8 px','16 px'],'8 px'],['windowDisplay','Target display','Choose where layout commands place windows.','select',['Current display','Display with pointer','Primary display'],'Current display'],['windowCycle','Repeat shortcut to cycle sizes','Cycle between half, one-third and two-thirds.','toggle',null,true],['windowRestore','Remember previous bounds','Enable the Restore Window command.','toggle',null,true]],
 notes:[['Writing'],['notesEnabled','Enable Notes','Offer notes in the launcher.','toggle',null,true],['notesFormat','Default format','Start with plain text or Markdown.','select',['Markdown','Plain text'],'Markdown'],['notesFont','Editor size','Choose a readable writing size.','select',['16 px','18 px','20 px'],'16 px'],['notesPin','Keep notes window on top','Apply to the notes window only.','toggle',null,false],['notesSave','Save drafts automatically','Retain sample drafts in this browser when storage is available.','toggle',null,true]],
